import sys, random, math
from array import array
from math import sumprod


def numbers():
    for line in sys.stdin.buffer:
        for x in line.split():
            yield int(x)


it = numbers()
sub, n, P = next(it), next(it), next(it)
A = [array("I", (next(it) for _ in range(n))) for _ in range(n)]
B = [array("I", (next(it) for _ in range(n))) for _ in range(n)]
T = math.ceil(42 / math.log(P))
rng = random.SystemRandom()
out = []


def solve(l, r, rows):
    if not rows:
        return
    if r - l == 1:
        for i in rows:
            z = sumprod(A[i], (row[l] for row in B)) % P
            if z:
                out.append((i + 1, l + 1, z))
        return
    keep = []
    unknown = rows
    for rep in range(T):
        if not unknown:
            break
        v = [rng.randrange(P) for _ in range(r - l)]
        w = [sumprod(row[l:r], v) % P for row in B]
        remain = []
        for i in unknown:
            z = sumprod(A[i], w) % P
            if z:
                keep.append(i)
            else:
                remain.append(i)
        unknown = remain
    mid = (l + r) // 2
    solve(l, mid, keep)
    solve(mid, r, keep)


solve(0, n, list(range(n)))
print("\n".join(" ".join(map(str, t)) for t in sorted(out)))

